import{_ as e,o as r,c as t,b3 as h}from"./chunks/framework.VnelH-cX.js";const q=JSON.parse('{"title":"功能设置","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings/function.md","filePath":"guide/settings/function.md","lastUpdated":1786700458000}'),i={name:"guide/settings/function.md"};function o(l,a,n,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[h('<h1 id="功能设置" tabindex="-1">功能设置 <a class="header-anchor" href="#功能设置" aria-label="Permalink to &quot;功能设置&quot;">​</a></h1><p>功能设置用于配置 Wing Shot 的各项核心能力与默认行为，包括截图、绘制、固定到屏幕、翻译、全屏画布、视频录制以及输出命名等。</p><h2 id="截图" tabindex="-1">截图 <a class="header-anchor" href="#截图" aria-label="Permalink to &quot;截图&quot;">​</a></h2><h3 id="查找窗口子元素" tabindex="-1">查找窗口子元素 <a class="header-anchor" href="#查找窗口子元素" aria-label="Permalink to &quot;查找窗口子元素&quot;">​</a></h3><p>自动框选时是否查找窗口的内部控件等内容</p><h3 id="取消截图-的弹窗提示" tabindex="-1">“取消截图&quot;的弹窗提示 <a class="header-anchor" href="#取消截图-的弹窗提示" aria-label="Permalink to &quot;“取消截图&quot;的弹窗提示&quot;">​</a></h3><p>通过快捷键取消截图时，是否弹窗提示</p><h3 id="文本识别后自动执行" tabindex="-1">文本识别后自动执行 <a class="header-anchor" href="#文本识别后自动执行" aria-label="Permalink to &quot;文本识别后自动执行&quot;">​</a></h3><p>使用文本识别工具后，自动完成选项中的操作。</p><ul><li><strong>无操作</strong></li><li><strong>复制文本</strong>：自动复制识别到的文本内容</li><li><strong>复制文本并关闭窗口</strong>：自动复制识别到的文本内容然后结束截图</li><li>文本识别-复制文本：仅在通过<strong>文本识别</strong>快捷功能识别文本时自动复制识别到的文本内容</li><li>文本识别-复制文本并关闭窗口：仅在通过<strong>文本识别</strong>快捷功能识别文本时自动复制识别到的文本内容然后结束截图</li></ul><h3 id="文本识别复制时复制文本" tabindex="-1">文本识别复制时复制文本 <a class="header-anchor" href="#文本识别复制时复制文本" aria-label="Permalink to &quot;文本识别复制时复制文本&quot;">​</a></h3><p>使用文本识别工具识别文本后，复制时复制识别到的文本，而非截图的图像内容</p><h3 id="双击复制到剪贴板" tabindex="-1">双击复制到剪贴板 <a class="header-anchor" href="#双击复制到剪贴板" aria-label="Permalink to &quot;双击复制到剪贴板&quot;">​</a></h3><p>截图时双击窗口即可复制截图到剪贴板</p><h3 id="截取当前具有焦点的窗口时复制到剪贴板" tabindex="-1">截取当前具有焦点的窗口时复制到剪贴板 <a class="header-anchor" href="#截取当前具有焦点的窗口时复制到剪贴板" aria-label="Permalink to &quot;截取当前具有焦点的窗口时复制到剪贴板&quot;">​</a></h3><p>截取焦点窗口时将图像数据写入到剪贴板</p><h3 id="截取全屏时复制到剪贴板" tabindex="-1">截取全屏时复制到剪贴板 <a class="header-anchor" href="#截取全屏时复制到剪贴板" aria-label="Permalink to &quot;截取全屏时复制到剪贴板&quot;">​</a></h3><p>截取全屏时将图像数据写入到剪贴板</p><h3 id="复制图片文件到剪贴板" tabindex="-1">复制图片文件到剪贴板 <a class="header-anchor" href="#复制图片文件到剪贴板" aria-label="Permalink to &quot;复制图片文件到剪贴板&quot;">​</a></h3><p>截图复制时选择先保存文件然后复制文件路径，而非复制图像数据</p><h3 id="复制后自动保存" tabindex="-1">复制后自动保存 <a class="header-anchor" href="#复制后自动保存" aria-label="Permalink to &quot;复制后自动保存&quot;">​</a></h3><p>复制截图后自动保存到指定目录</p><h3 id="一键快速保存" tabindex="-1">一键快速保存 <a class="header-anchor" href="#一键快速保存" aria-label="Permalink to &quot;一键快速保存&quot;">​</a></h3><p>新增快速保存按钮，支持一键保存到指定目录</p><h3 id="文件保存目录" tabindex="-1">文件保存目录 <a class="header-anchor" href="#文件保存目录" aria-label="Permalink to &quot;文件保存目录&quot;">​</a></h3><p>自动保存等保存方式保存的目录</p><h3 id="保存文件格式" tabindex="-1">保存文件格式 <a class="header-anchor" href="#保存文件格式" aria-label="Permalink to &quot;保存文件格式&quot;">​</a></h3><p>自动保存等保存方式使用的图片格式</p><h4 id="保存到云端" tabindex="-1">保存到云端 <a class="header-anchor" href="#保存到云端" aria-label="Permalink to &quot;保存到云端&quot;">​</a></h4><p>支持 S3 等协议，一键上传到云端并复制上传后的链接</p><h2 id="绘制" tabindex="-1">绘制 <a class="header-anchor" href="#绘制" aria-label="Permalink to &quot;绘制&quot;">​</a></h2><h3 id="锁定绘制工具" tabindex="-1">锁定绘制工具 <a class="header-anchor" href="#锁定绘制工具" aria-label="Permalink to &quot;锁定绘制工具&quot;">​</a></h3><p>绘制某个元素结束后保持激活当前的绘制工具，而非切换选择工具</p><h3 id="更精细的大小控制" tabindex="-1">更精细的大小控制 <a class="header-anchor" href="#更精细的大小控制" aria-label="Permalink to &quot;更精细的大小控制&quot;">​</a></h3><p>使用滑块更精细的修改绘制元素的描边、大小等样式</p><h3 id="独立的工具样式" tabindex="-1">独立的工具样式 <a class="header-anchor" href="#独立的工具样式" aria-label="Permalink to &quot;独立的工具样式&quot;">​</a></h3><p>每种绘制元素拥有独立的样式配置，而非通用的样式</p><h3 id="禁用选择相同类型的元素" tabindex="-1">禁用选择相同类型的元素 <a class="header-anchor" href="#禁用选择相同类型的元素" aria-label="Permalink to &quot;禁用选择相同类型的元素&quot;">​</a></h3><p>激活绘制工具时默认允许通过鼠标快速选择该工具绘制出的同类型元素，可以禁用某些工具下的快速选择，避免绘制时干扰</p><h2 id="固定到屏幕" tabindex="-1">固定到屏幕 <a class="header-anchor" href="#固定到屏幕" aria-label="Permalink to &quot;固定到屏幕&quot;">​</a></h2><h3 id="默认工具" tabindex="-1">默认工具 <a class="header-anchor" href="#默认工具" aria-label="Permalink to &quot;默认工具&quot;">​</a></h3><h3 id="以鼠标为中心缩放" tabindex="-1">以鼠标为中心缩放 <a class="header-anchor" href="#以鼠标为中心缩放" aria-label="Permalink to &quot;以鼠标为中心缩放&quot;">​</a></h3><p>缩放固定到屏幕的内容时，以鼠标为缩放中心进行缩放</p><h4 id="窗口初始位置" tabindex="-1">窗口初始位置 <a class="header-anchor" href="#窗口初始位置" aria-label="Permalink to &quot;窗口初始位置&quot;">​</a></h4><p>固定到屏幕窗口的初始显示位置</p><h4 id="自动文本识别" tabindex="-1">自动文本识别 <a class="header-anchor" href="#自动文本识别" aria-label="Permalink to &quot;自动文本识别&quot;">​</a></h4><p>固定截图后自动对截图进行文本识别</p><h4 id="自动缩放窗口" tabindex="-1">自动缩放窗口 <a class="header-anchor" href="#自动缩放窗口" aria-label="Permalink to &quot;自动缩放窗口&quot;">​</a></h4><p>固定到屏幕的内容过大超出屏幕范围时，自动缩放窗口以适应屏幕大小</p><h4 id="固定截图后自动复制到剪贴板" tabindex="-1">固定截图后自动复制到剪贴板 <a class="header-anchor" href="#固定截图后自动复制到剪贴板" aria-label="Permalink to &quot;固定截图后自动复制到剪贴板&quot;">​</a></h4><p>固定截图后复制截图内容到剪贴板</p><h2 id="文本识别" tabindex="-1">文本识别 <a class="header-anchor" href="#文本识别" aria-label="Permalink to &quot;文本识别&quot;">​</a></h2><h3 id="文本识别模型" tabindex="-1">文本识别模型 <a class="header-anchor" href="#文本识别模型" aria-label="Permalink to &quot;文本识别模型&quot;">​</a></h3><p>选择文本识别使用的文本识别模型。</p><ul><li>RapidOCR V5 支持日语等多语言识别</li><li>RapidOCR V4 相比 V5 通常能获得更好的中文识别效果</li></ul><h3 id="视觉理解模型" tabindex="-1">视觉理解模型 <a class="header-anchor" href="#视觉理解模型" aria-label="Permalink to &quot;视觉理解模型&quot;">​</a></h3><p>将图片转为 HTML 的视觉理解模型</p><h3 id="图片转为-html-的-system-提示词" tabindex="-1">图片转为 HTML 的 System 提示词 <a class="header-anchor" href="#图片转为-html-的-system-提示词" aria-label="Permalink to &quot;图片转为 HTML 的 System 提示词&quot;">​</a></h3><p>图片转为 HTML 的 System 提示词，转换时使用</p><h2 id="翻译" tabindex="-1">翻译 <a class="header-anchor" href="#翻译" aria-label="Permalink to &quot;翻译&quot;">​</a></h2><h3 id="源语言" tabindex="-1">源语言 <a class="header-anchor" href="#源语言" aria-label="Permalink to &quot;源语言&quot;">​</a></h3><p>选择需要翻译的原文语言。支持自动识别语言或手动指定具体语言（如英语、日语、韩语等）</p><h3 id="目标语言" tabindex="-1">目标语言 <a class="header-anchor" href="#目标语言" aria-label="Permalink to &quot;目标语言&quot;">​</a></h3><p>选择翻译的目标语言。支持多种语言，包括简体中文、繁体中文、英语等</p><h3 id="翻译服务" tabindex="-1">翻译服务 <a class="header-anchor" href="#翻译服务" aria-label="Permalink to &quot;翻译服务&quot;">​</a></h3><p>选择使用的翻译服务提供商</p><h3 id="翻译领域" tabindex="-1">翻译领域 <a class="header-anchor" href="#翻译领域" aria-label="Permalink to &quot;翻译领域&quot;">​</a></h3><p>根据翻译内容的专业领域选择相应的翻译模式</p><h3 id="优化-ai-翻译的排版" tabindex="-1">优化 AI 翻译的排版 <a class="header-anchor" href="#优化-ai-翻译的排版" aria-label="Permalink to &quot;优化 AI 翻译的排版&quot;">​</a></h3><p>文本识别翻译依赖翻译原文和翻译结果具有相同的排版关系，而 AI 的输出可能存在排版错误。开启后将尝试优化排版，但显示出的内容顺序可能与原文不一致</p><h3 id="api-配置" tabindex="-1">API 配置 <a class="header-anchor" href="#api-配置" aria-label="Permalink to &quot;API 配置&quot;">​</a></h3><p>点击&quot;添加 API 配置&quot;按钮，配置第三方翻译服务的 API 密钥。</p><h3 id="翻译提示词" tabindex="-1">翻译提示词 <a class="header-anchor" href="#翻译提示词" aria-label="Permalink to &quot;翻译提示词&quot;">​</a></h3><p>自定义翻译的 AI 提示词，可以根据需要调整翻译风格和要求。系统会使用你设置的提示词来指导 AI 进行翻译。</p><h2 id="全屏画布" tabindex="-1">全屏画布 <a class="header-anchor" href="#全屏画布" aria-label="Permalink to &quot;全屏画布&quot;">​</a></h2><h3 id="默认工具-1" tabindex="-1">默认工具 <a class="header-anchor" href="#默认工具-1" aria-label="Permalink to &quot;默认工具&quot;">​</a></h3><p>进入全屏画布后，默认激活的工具。</p><h2 id="视频录制" tabindex="-1">视频录制 <a class="header-anchor" href="#视频录制" aria-label="Permalink to &quot;视频录制&quot;">​</a></h2><h3 id="帧率" tabindex="-1">帧率 <a class="header-anchor" href="#帧率" aria-label="Permalink to &quot;帧率&quot;">​</a></h3><p>视频录制采样帧率</p><h3 id="视频清晰度" tabindex="-1">视频清晰度 <a class="header-anchor" href="#视频清晰度" aria-label="Permalink to &quot;视频清晰度&quot;">​</a></h3><p>视频录制的画面清晰度</p><h3 id="动图清晰度" tabindex="-1">动图清晰度 <a class="header-anchor" href="#动图清晰度" aria-label="Permalink to &quot;动图清晰度&quot;">​</a></h3><p>动图的画面清晰度</p><h3 id="动图帧率" tabindex="-1">动图帧率 <a class="header-anchor" href="#动图帧率" aria-label="Permalink to &quot;动图帧率&quot;">​</a></h3><p>动图的采样帧率</p><h3 id="动图格式" tabindex="-1">动图格式 <a class="header-anchor" href="#动图格式" aria-label="Permalink to &quot;动图格式&quot;">​</a></h3><p>支持 GIF、WebP、APng 等动图格式</p><h3 id="麦克风设备" tabindex="-1">麦克风设备 <a class="header-anchor" href="#麦克风设备" aria-label="Permalink to &quot;麦克风设备&quot;">​</a></h3><p>视频录制使用的录音设备</p><h3 id="编码器" tabindex="-1">编码器 <a class="header-anchor" href="#编码器" aria-label="Permalink to &quot;编码器&quot;">​</a></h3><p>视频编码器</p><h3 id="编码速率" tabindex="-1">编码速率 <a class="header-anchor" href="#编码速率" aria-label="Permalink to &quot;编码速率&quot;">​</a></h3><p>编码速率越高，设备的性能要求越低</p><h3 id="启用硬件加速" tabindex="-1">启用硬件加速 <a class="header-anchor" href="#启用硬件加速" aria-label="Permalink to &quot;启用硬件加速&quot;">​</a></h3><p>加速视频处理</p><h3 id="保存目录" tabindex="-1">保存目录 <a class="header-anchor" href="#保存目录" aria-label="Permalink to &quot;保存目录&quot;">​</a></h3><p>视频的保存目录</p><h3 id="录制画面中隐藏工具栏" tabindex="-1">录制画面中隐藏工具栏 <a class="header-anchor" href="#录制画面中隐藏工具栏" aria-label="Permalink to &quot;录制画面中隐藏工具栏&quot;">​</a></h3><p>视频录制时，在视频画面中隐藏视频录制的工具栏</p><h2 id="托盘" tabindex="-1">托盘 <a class="header-anchor" href="#托盘" aria-label="Permalink to &quot;托盘&quot;">​</a></h2><h3 id="左键点击后" tabindex="-1">左键点击后 <a class="header-anchor" href="#左键点击后" aria-label="Permalink to &quot;左键点击后&quot;">​</a></h3><p>支持配置托盘点击后的行为</p><h2 id="输出" tabindex="-1">输出 <a class="header-anchor" href="#输出" aria-label="Permalink to &quot;输出&quot;">​</a></h2><p>可以设置图片、视频的默认文件名格式</p>',105)])])}const b=e(i,[["render",o]]);export{q as __pageData,b as default};
